import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard"; import { Screen } from "../../ui/Screen"; import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase"; import { getVendorWorkspace, saveVendorBankAccount, submitVendorKyc, updateVendorShop } from "./vendor.api";

export function VendorSettingsScreen() { const user = firebaseAuth?.currentUser ?? null; const queryClient = useQueryClient(); const workspace = useQuery({ queryKey: ["vendor", "workspace"], queryFn: () => getVendorWorkspace(user!), enabled: Boolean(user) }); const shop = workspace.data?.shops[0]; const [shopName, setShopName] = useState(""); const [description, setDescription] = useState(""); const [bank, setBank] = useState({ provider: "BANK" as "BANK" | "BKASH" | "NAGAD" | "ROCKET", accountName: "", accountNumber: "" }); const [document, setDocument] = useState({ storageKey: "", checksum: "" }); useEffect(() => { if (shop) { setShopName(shop.name); setDescription(shop.description ?? ""); } }, [shop]); const refresh = () => queryClient.invalidateQueries({ queryKey: ["vendor", "workspace"] }); const saveShop = useMutation({ mutationFn: () => updateVendorShop(user!, shop!.id, { version: shop!.version, name: shopName, description: description || null }), onSuccess: refresh }); const saveBank = useMutation({ mutationFn: () => saveVendorBankAccount(user!, { ...bank, isDefault: true }), onSuccess: async () => { setBank({ provider: "BANK", accountName: "", accountNumber: "" }); await refresh(); } }); const saveKyc = useMutation({ mutationFn: () => submitVendorKyc(user!, { documents: [{ documentType: "TRADE_LICENSE", storageKey: document.storageKey, mimeType: "application/pdf", checksum: document.checksum }] }), onSuccess: refresh }); if (workspace.isLoading) return <Screen title="Vendor settings"><ActivityIndicator color={colors.primary} /></Screen>; return <Screen eyebrow="SELLER CENTER" title={workspace.data?.displayName || "Vendor settings"} description={`Account status: ${workspace.data?.status || "UNKNOWN"}`}><ModuleCard title="Shop profile" meta={shop?.slug}><Field label="Shop name" value={shopName} onChangeText={setShopName} /><Field label="Description" multiline value={description} onChangeText={setDescription} /><Action busy={saveShop.isPending} label="Save shop" onPress={() => saveShop.mutate()} /></ModuleCard><ModuleCard title="KYC verification" meta={workspace.data?.kycSubmissions[0] ? `Latest: ${workspace.data.kycSubmissions[0].status}` : "No submission yet"}><Text style={styles.muted}>Enter the private object-storage key and SHA checksum created by the upload flow.</Text><Field label="Trade license storage key" value={document.storageKey} onChangeText={(storageKey) => setDocument({ ...document, storageKey })} /><Field label="SHA checksum" value={document.checksum} onChangeText={(checksum) => setDocument({ ...document, checksum })} /><Action busy={saveKyc.isPending} label="Submit KYC" onPress={() => saveKyc.mutate()} /></ModuleCard><ModuleCard title="Payout accounts" meta="Full account numbers are encrypted and never returned.">{workspace.data?.bankAccounts.map((account) => <View key={account.id} style={styles.account}><Text style={styles.accountName}>{account.provider} · {account.accountNumberMasked}</Text><Text style={styles.muted}>{account.accountName}{account.isDefault ? " · Default" : ""}</Text></View>)}<View style={styles.providers}>{(["BANK", "BKASH", "NAGAD", "ROCKET"] as const).map((provider) => <Pressable key={provider} onPress={() => setBank({ ...bank, provider })} style={[styles.chip, bank.provider === provider && styles.active]}><Text style={[styles.chipText, bank.provider === provider && styles.activeText]}>{provider}</Text></Pressable>)}</View><Field label="Account name" value={bank.accountName} onChangeText={(accountName) => setBank({ ...bank, accountName })} /><Field label="Account number" secureTextEntry value={bank.accountNumber} onChangeText={(accountNumber) => setBank({ ...bank, accountNumber })} /><Action busy={saveBank.isPending} label="Save payout account" onPress={() => saveBank.mutate()} />{[saveShop.error, saveKyc.error, saveBank.error].find(Boolean) ? <Text style={styles.error}>{[saveShop.error, saveKyc.error, saveBank.error].find(Boolean)?.message}</Text> : null}</ModuleCard></Screen>; }
function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...rest } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, rest.multiline && styles.multiline]} {...rest} /></View>; } function Action({ busy, label, onPress }: { busy: boolean; label: string; onPress(): void }) { return <Pressable disabled={busy} onPress={onPress} style={styles.button}>{busy ? <ActivityIndicator color="#fff" /> : <Text style={styles.buttonText}>{label}</Text>}</Pressable>; }
const styles = StyleSheet.create({ field: { gap: 5 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, multiline: { minHeight: 90, paddingVertical: 10, textAlignVertical: "top" }, button: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 46 }, buttonText: { color: "#fff", fontWeight: "900" }, muted: { color: colors.muted, lineHeight: 20 }, providers: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, paddingHorizontal: 11, paddingVertical: 7 }, active: { backgroundColor: colors.primary }, chipText: { color: colors.text, fontSize: 10, fontWeight: "900" }, activeText: { color: "#fff" }, account: { borderBottomColor: colors.border, borderBottomWidth: 1, paddingBottom: spacing.sm }, accountName: { color: colors.text, fontWeight: "900" }, error: { color: colors.danger } });
